using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Rustegon.Driver.Internal.Codec;
using Xunit;

namespace Rustegon.Driver.Tests;

/// <summary>
/// TC-DRV-NET-001 (FR-DRV-001, FR-DRV-003, FR-DOC-001/003, PD-075): runner of the shared codec
/// vectors <c>drivers/conformance/codec/{values,documents,invalid}.yaml</c> (conformance README §3,
/// generated by <c>crates/rustegon-doc/tests/driver_vectors.rs</c>). Every vector is its own test
/// case, named <c>&lt;file&gt;#&lt;section&gt;/&lt;name&gt;</c>, so a failure names the vector.
/// </summary>
public sealed class CodecConformanceTests
{
    private const string Missing = "<codec vectors absent>";

    private static string Dir => Path.Combine(TestPaths.Conformance, "codec");

    private static readonly string[] Files = ["values.yaml", "documents.yaml", "invalid.yaml"];

    public static TheoryData<string> Vectors()
    {
        var data = new TheoryData<string>();
        if (!Directory.Exists(Dir))
        {
            data.Add(Missing);
            return data;
        }

        foreach (string file in Files)
        {
            var root = (Dictionary<string, object?>)ConformanceYaml.Load(Path.Combine(Dir, file))!;
            foreach ((string section, object? entries) in root)
            {
                if (entries is not List<object?> list)
                {
                    continue;
                }

                foreach (object? e in list)
                {
                    data.Add($"{file}#{section}/{Str((Dictionary<string, object?>)e!, "name")}");
                }
            }
        }

        return data;
    }

    [Fact]
    public void tc_drv_net_001_conformance_codec_vector_files_are_complete()
    {
        Assert.True(Directory.Exists(Dir), "drivers/conformance/codec is missing");
        foreach (string file in Files)
        {
            var root = (Dictionary<string, object?>)ConformanceYaml.Load(Path.Combine(Dir, file))!;
            Assert.Equal(1L, root["version"]);
        }

        // Sections named by the README; a renamed section must not silently drop its vectors.
        string[] names = [.. Vectors().Select(row => row.Data)];
        foreach (string section in new[]
        {
            "values.yaml#values/", "values.yaml#noncanonical/", "documents.yaml#documents/", "documents.yaml#noncanonical/",
            "invalid.yaml#documents/", "invalid.yaml#values/", "invalid.yaml#json/",
        })
        {
            Assert.Contains(names, n => n.StartsWith(section, StringComparison.Ordinal));
        }

        Assert.Equal(names.Length, names.Distinct(StringComparer.Ordinal).Count());
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public void tc_drv_net_001_conformance_codec_vectors(string vector)
    {
        if (vector == Missing)
        {
            Assert.Skip("drivers/conformance/codec not present");
        }

        int hash = vector.IndexOf('#', StringComparison.Ordinal);
        int slash = vector.IndexOf('/', hash);
        string file = vector[..hash];
        string section = vector[(hash + 1)..slash];
        string name = vector[(slash + 1)..];
        var root = (Dictionary<string, object?>)ConformanceYaml.Load(Path.Combine(Dir, file))!;
        Dictionary<string, object?> v = ((List<object?>)root[section]!)
            .Cast<Dictionary<string, object?>>()
            .Single(e => Str(e, "name") == name);

        switch ((file, section))
        {
            case ("values.yaml", "values"):
                CheckValue(v);
                break;
            case ("values.yaml", "noncanonical"):
                CheckNoncanonicalValue(v);
                break;
            case ("documents.yaml", "documents"):
                CheckDocument(v);
                break;
            case ("documents.yaml", "noncanonical"):
                CheckNoncanonicalDocument(v);
                break;
            case ("invalid.yaml", "documents"):
                CheckRejected(v, () => RDocReader.ReadDocument(Hex(v, "hex")));
                break;
            case ("invalid.yaml", "values"):
                CheckRejected(v, () => RDocReader.ReadValue(Hex(v, "hex")));
                break;
            case ("invalid.yaml", "json"):
                string json = Str(v, "json");
                CheckRejected(v, Str(v, "kind") switch
                {
                    "document" => () => RDocument.FromJson(json),
                    "value" => () => RDocValue.FromJson(json),
                    string k => throw new InvalidDataException($"unknown kind '{k}'"),
                });
                break;
            default:
                throw new InvalidDataException($"no runner for {file}#{section}");
        }
    }

    /// <summary>README §3 values: input and ext_json parse to the value of <c>hex</c>; <c>hex</c> prints both JSON modes.</summary>
    private static void CheckValue(Dictionary<string, object?> v)
    {
        byte[] hex = Hex(v, "hex");
        if (!DecodeOnly(v))
        {
            Assert.Equal(Convert.ToHexStringLower(hex), Convert.ToHexStringLower(RDocWriter.ValueToBytes(RDocValue.FromJson(Str(v, "input")))));
            Assert.Equal(Convert.ToHexStringLower(hex), Convert.ToHexStringLower(RDocWriter.ValueToBytes(RDocValue.FromJson(Str(v, "ext_json")))));
        }

        RDocValue decoded = RDocReader.ReadValue(hex);
        Assert.Equal(Str(v, "ext_json"), decoded.ToJson(RDocJsonMode.Canonical));
        Assert.Equal(Str(v, "extended_json"), decoded.ToJson(RDocJsonMode.Extended));
    }

    private static void CheckNoncanonicalValue(Dictionary<string, object?> v)
    {
        RDocValue decoded = RDocReader.ReadValue(Hex(v, "hex"));
        Assert.Equal(Str(v, "canonical_hex"), Convert.ToHexStringLower(RDocWriter.ValueToBytes(decoded)));
        Assert.Equal(Str(v, "ext_json"), decoded.ToJson());
    }

    /// <summary>README §3 documents: byte-exact both ways, canonical flag, and the index hash of every field name.</summary>
    private static void CheckDocument(Dictionary<string, object?> v)
    {
        byte[] hex = Hex(v, "hex");
        string json = Str(v, "ext_json");
        if (!DecodeOnly(v))
        {
            Assert.Equal(Convert.ToHexStringLower(hex), Convert.ToHexStringLower(RDocument.FromJson(json).ToBytes()));
        }

        Assert.True(RDocReader.IsCanonicalFlagSet(hex));
        RDocument decoded = RDocReader.ReadDocument(hex);
        Assert.Equal(json, decoded.ToJson());
        Assert.Equal(Convert.ToHexStringLower(hex), Convert.ToHexStringLower(decoded.ToBytes()));
        if (v["name_hash16"] is List<object?> hashes)
        {
            foreach (Dictionary<string, object?> h in hashes.Cast<Dictionary<string, object?>>())
            {
                ushort expected = Convert.ToUInt16(Str(h, "hash"), 16);
                Assert.Equal(expected, RDocFormat.NameHash16(Encoding.UTF8.GetBytes(Str(h, "name"))));

                // The index stores the hash little-endian: it must be in the encoded document.
                Assert.True(hex.AsSpan().IndexOf([(byte)expected, (byte)(expected >> 8)]) >= 0, $"hash {Str(h, "hash")} not in the index");
            }
        }
    }

    private static void CheckNoncanonicalDocument(Dictionary<string, object?> v)
    {
        byte[] hex = Hex(v, "hex");
        Assert.False(RDocReader.IsCanonicalFlagSet(hex));
        RDocument decoded = RDocReader.ReadDocument(hex);
        Assert.Equal(Str(v, "canonical_hex"), Convert.ToHexStringLower(decoded.ToBytes()));
        Assert.Equal(Str(v, "ext_json"), decoded.ToJson());
    }

    /// <summary>README §3 invalid: rejected with an <see cref="RDocException"/> carrying the vector's code.</summary>
    private static void CheckRejected(Dictionary<string, object?> v, Func<object> parse)
    {
        RDocException e = Assert.Throws<RDocException>(parse);
        Assert.Equal((long)v["code"]!, e.Code);
    }

    private static bool DecodeOnly(Dictionary<string, object?> v) => v.TryGetValue("decode_only", out object? d) && d is true;

    private static string Str(Dictionary<string, object?> v, string key) =>
        v.TryGetValue(key, out object? s) && s is string str ? str : throw new InvalidDataException($"missing string '{key}'");

    private static byte[] Hex(Dictionary<string, object?> v, string key) => Convert.FromHexString(Str(v, key));
}
